ruleContent.content:
@js:
var tokenMatch = src.match(/token\s*=\s*"([^"]+)"/);
var html = src;
if (tokenMatch) {
    var token = tokenMatch[1];
    var tourl = baseUrl + "?challenge=" + encodeURIComponent(token);
    html = java.ajax(tourl);
}
var section = html.match(/<section[^>]*>\s*([\s\S]*?)\s*<\/section>/i);
if (!section) {
    "";
} else {
    var text = section[1]
        .replace(/<br\s*\/?>/gi, "\n")
        .replace(/<\/p>\s*<p[^>]*>/gi, "\n")
        .replace(/<\/?p[^>]*>/gi, "")
        .trim();
    text;
}

ruleToc.chapterList:
@js:
var bid = "";
var mm = baseUrl.match(/read\/(\d+)/);
if (mm) bid = mm[1];
var result = [];
if (bid) {
    var key = source.getKey();
    try {
        var resp = java.post(key + "/novel/clist/", "bid=" + bid, {"X-Requested-With": "XMLHttpRequest", "Content-Type": "application/x-www-form-urlencoded"});
        var body = String(resp.body());
        if (body.indexOf("\"data\"") > -1) {
            var json = JSON.parse(body);
            var data = json.data;
            if (data && data.length > 0) {
                var volume = "";
                for (var i = 0; i < data.length; i++) {
                    var item = data[i];
                    if (String(item.ctype) == "1") {
                        volume = item.title;
                        continue;
                    }
                    result.push({title: item.title, url: key + "/read/" + bid + "/p" + item.ordernum + ".html", volume: volume});
                }
            }
        }
    } catch (e) {}
    if (result.length == 0) {
        var html = "";
        try {
            html = String(java.post(key + "/novel/html", "bid=" + bid, {"X-Requested-With": "XMLHttpRequest"}).body());
        } catch (e2) {}
        if (!html || html.indexOf("p1.html") == -1) {
            try {
                html = String(java.ajax(key + "/read/" + bid + "/"));
            } catch (e3) {}
        }
        var reg = /<a href="\/read\/\d+\/p(\d+)\.html"[^>]*>([^<]*)<\/a>/g;
        var seen = {};
        var found = [];
        var r;
        while ((r = reg.exec(html)) != null) {
            var num = parseInt(r[1], 10);
            if (!num || seen[num] == 1) continue;
            seen[num] = 1;
            found.push({num: num, title: r[2], url: key + "/read/" + bid + "/p" + num + ".html"});
        }
        found.sort(function(a, b) { return a.num - b.num; });
        for (var j = 0; j < found.length; j++) {
            result.push({title: found[j].title, url: found[j].url, volume: ""});
        }
    }
}
result;
